WITH months AS (SELECT DISTINCT CAST(DATE_TRUNC('month', date_day) AS DATE) AS month_start FROM {{ ref('time_spine') }}), scope_cards AS (SELECT card_id, member_id, card_type, valid_from, valid_until, ended_at FROM {{ ref('cards') }} WHERE card_type IN ('悦享年卡', '家庭季卡')), card_date_checks AS (SELECT card_id, member_id, card_type, valid_from, valid_until, ended_at, CASE WHEN valid_from IS NOT NULL AND valid_until IS NOT NULL AND valid_from < valid_until AND (ended_at IS NULL OR (ended_at > valid_from AND ended_at < valid_until)) THEN TRUE ELSE FALSE END AS is_normal FROM scope_cards), card_month_eligibility AS (SELECT m.month_start, c.member_id, c.card_id, CASE WHEN c.is_normal AND c.valid_from <= CAST(m.month_start + INTERVAL 1 MONTH - INTERVAL 1 DAY AS DATE) AND CAST(m.month_start + INTERVAL 1 MONTH - INTERVAL 1 DAY AS DATE) < c.valid_until AND (c.ended_at IS NULL OR CAST(m.month_start + INTERVAL 1 MONTH - INTERVAL 1 DAY AS DATE) < c.ended_at) THEN 1 ELSE 0 END AS is_eligible FROM months m CROSS JOIN card_date_checks c), eligible_member_months AS (SELECT DISTINCT month_start, member_id FROM card_month_eligibility WHERE is_eligible = 1), valid_orders AS (SELECT member_id, ordered_at, paid_cents, refund_cents FROM {{ ref('orders') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0), member_month_orders AS (SELECT member_id, CAST(DATE_TRUNC('month', ordered_at) AS DATE) AS month_start, COUNT(*) AS valid_order_count, SUM(paid_cents - refund_cents) AS net_sales_cents FROM valid_orders GROUP BY member_id, CAST(DATE_TRUNC('month', ordered_at) AS DATE)), eligible_purchases AS (SELECT e.month_start, e.member_id, COALESCE(o.valid_order_count, 0) AS valid_order_count, COALESCE(o.net_sales_cents, 0) AS net_sales_cents FROM eligible_member_months e LEFT JOIN member_month_orders o ON e.member_id = o.member_id AND e.month_start = o.month_start), monthly_agg AS (SELECT month_start, COUNT(DISTINCT CASE WHEN valid_order_count >= 1 THEN member_id END) AS monthly_paid_buyer_count, SUM(valid_order_count) AS monthly_paid_order_count, SUM(net_sales_cents) AS monthly_paid_sales_cents, COUNT(DISTINCT CASE WHEN valid_order_count >= 2 THEN member_id END) AS monthly_paid_repeat_buyer_count FROM eligible_purchases GROUP BY month_start) SELECT m.month_start, COALESCE(a.monthly_paid_buyer_count, 0) AS monthly_paid_buyer_count, COALESCE(a.monthly_paid_order_count, 0) AS monthly_paid_order_count, COALESCE(a.monthly_paid_sales_cents, 0) AS monthly_paid_sales_cents, COALESCE(a.monthly_paid_repeat_buyer_count, 0) AS monthly_paid_repeat_buyer_count FROM months m LEFT JOIN monthly_agg a ON m.month_start = a.month_start